<?php require '../config/database.php'; require '../includes/auth.php'; require_student();$base_path='../';$page_title='Saved Jobs';$stmt=$pdo->prepare('SELECT j.* FROM saved_jobs s JOIN jobs j ON j.id=s.job_id WHERE s.user_id=? ORDER BY s.created_at DESC');$stmt->execute([$_SESSION['user']['id']]);$jobs=$stmt->fetchAll();include '../includes/header.php'; ?>
<section class="container py-5"><h1 class="section-title mb-4">Saved jobs</h1><div class="row g-4"><?php foreach($jobs as $job): ?><div class="col-md-6"><div class="card p-4"><h4><?= htmlspecialchars($job['title']) ?></h4><p class="text-muted"><?= htmlspecialchars($job['company']) ?> &middot; <?= htmlspecialchars($job['location']) ?></p><p><?= htmlspecialchars($job['description']) ?></p><form action="../actions/remove-job.php" method="post"><input type="hidden" name="job_id" value="<?= $job['id'] ?>"><button class="btn btn-outline-danger" data-confirm="Remove this job from saved jobs?">Remove</button></form></div></div><?php endforeach; ?><?php if(!$jobs): ?><p>You have not saved any jobs yet. <a href="jobs.php">Browse jobs</a>.</p><?php endif; ?></div></section><?php include '../includes/footer.php'; ?>
